1	// Command edgefleet is the 验证者与边缘节点机群管理平台 entry point.
2	package main
3	
4	import (
5		"flag"
6		"fmt"
7		"io"
8		"os"
9		"time"
10	
11		"github.com/asdhoaiqqq/edgefleet-validator/edgefleet"
12	)
13	
14	func main() {
15		command := "demo"
16		if len(os.Args) > 1 {
17			command = os.Args[1]
18		}
19		switch command {
20		case "demo":
21			runDemo()
22		case "version":
23			fmt.Println("edgefleet 0.1.0")
24		case "heartbeat":
25			runHeartbeat(os.Args[2:])
26		case "help", "-h", "--help":
27			usage()
28		default:
29			fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
30			usage()
31			os.Exit(2)
32		}
33	}
34	
35	func usage() {
36		fmt.Println("usage: edgefleet [demo|version|heartbeat|help]")
37		fmt.Println()
38		fmt.Println("commands:")
39		fmt.Println("  demo       run the built-in evaluation demo")
40		fmt.Println("  version    print version")
41		fmt.Println("  heartbeat  receive, store and query real heartbeats")
42		fmt.Println("  help       show this help")
43		fmt.Println()
44		fmt.Println("run 'edgefleet heartbeat --help' for heartbeat input format and storage location")
45	}
46	
47	// defaultDataDir resolves the data directory: --data-dir flag, then the
48	// EDGEFLEET_DATA_DIR environment variable, then ~/.edgefleet.
49	func defaultDataDir() string {
50		if d := os.Getenv("EDGEFLEET_DATA_DIR"); d != "" {
51			return d
52		}
53		home, err := os.UserHomeDir()
54		if err != nil {
55			return ".edgefleet"
56		}
57		return home + "/.edgefleet"
58	}
59	
60	// die prints an error to stderr and exits with status 1.
61	func die(format string, args ...any) {
62		fmt.Fprintf(os.Stderr, "error: "+format+"\n", args...)
63		os.Exit(1)
64	}
65	
66	// parseTime parses an RFC3339 time flag, defaulting to now when empty.
67	func parseTimeFlag(value, flagName string) time.Time {
68		if value == "" {
69			return time.Now()
70		}
71		t, err := time.Parse(time.RFC3339, value)
72		if err != nil {
73			die("invalid %s %q: must be RFC3339 with timezone (e.g. 2026-10-01T12:00:00+08:00)", flagName, value)
74		}
75		return t
76	}
77	
78	func runHeartbeat(args []string) {
79		if len(args) == 0 {
80			heartbeatUsage()
81			return
82		}
83		switch args[0] {
84		case "submit":
85			cmdSubmit(args[1:])
86		case "health":
87			cmdHealth(args[1:])
88		case "history":
89			cmdHistory(args[1:])
90		case "help", "-h", "--help":
91			heartbeatUsage()
92		default:
93			fmt.Fprintf(os.Stderr, "unknown heartbeat command %q\n", args[0])
94			heartbeatUsage()
95			os.Exit(2)
96		}
97	}
98	
99	func heartbeatUsage() {
100		fmt.Println("usage: edgefleet heartbeat <submit|health|history> [flags]")
101		fmt.Println()
102		fmt.Println("commands:")
103		fmt.Println("  submit   receive heartbeats from stdin as a JSON array")
104		fmt.Println("  health   query node health from its latest telemetry")
105		fmt.Println("  history  list all heartbeats for a node, ascending by seq")
106		fmt.Println()
107		fmt.Println("input format (submit):")
108		fmt.Println("  A JSON array of heartbeat objects; every field is required.")
109		fmt.Println("    node          string   node id (non-empty, any length)")
110		fmt.Println("    seq           integer  sequence number (> 0)")
111		fmt.Println("    collected_at  string   RFC3339 with timezone, e.g. 2026-10-01T12:00:00+08:00")
112		fmt.Println("                           year 0000-9999; numeric offset hour 00-23 and")
113		fmt.Println("                           minute 00-59 on the minute (no seconds); +24:00")
114		fmt.Println("                           and out-of-range minutes like +00:60 are rejected,")
115		fmt.Println("                           not folded; must not be later than receive time")
116		fmt.Println("    version       string   version (non-empty, valid Unicode text)")
117		fmt.Println("    height        integer  block height (>= 0)")
118		fmt.Println("    missed        integer  cumulative missed duties (>= 0)")
119		fmt.Println()
120		fmt.Println("  example:")
121		fmt.Println(`    [{"node":"val-eu-1","seq":7,"collected_at":"2026-10-01T11:59:00+08:00",`)
122		fmt.Println(`      "version":"1.26.0","height":12345,"missed":0}]`)
123		fmt.Println()
124		fmt.Println("flags:")
125		fmt.Println("  submit   --data-dir DIR        data directory (default: $EDGEFLEET_DATA_DIR or ~/.edgefleet)")
126		fmt.Println("           --receive-time TIME   receive time, RFC3339 (default: now)")
127		fmt.Println("  health   --node ID             node id (required)")
128		fmt.Println("           --expected-version V  expected version (required)")
129		fmt.Println("           --tolerated-misses N  tolerated missed duties, >= 0 (required)")
130		fmt.Println("           --missed-since-seq S  seq of a saved heartbeat used as the")
131		fmt.Println("                                missed-duty baseline (optional, > 0)")
132		fmt.Println("           --at TIME             query time, RFC3339 (default: now)")
133		fmt.Println("           --data-dir DIR        data directory")
134		fmt.Println()
135		fmt.Println("  Without --missed-since-seq the missed-duty alarm uses the cumulative")
136		fmt.Println("  missed count of the latest heartbeat (missed in the output). With it,")
137		fmt.Println("  the alarm counts only missed duties newly recorded between the baseline")
138		fmt.Println("  heartbeat seq S and the latest one; a count strictly greater than")
139		fmt.Println("  --tolerated-misses alarms, equality does not. The output then shows the")
140		fmt.Println("  baseline seq, the baseline cumulative count and the new count. If the")
141		fmt.Println("  cumulative counter decreased between the baseline and the latest record")
142		fmt.Println("  (e.g. after a node reset), the new count is shown as 无法判断 and a")
143		fmt.Println("  累计漏签数回退 finding is reported; the baseline must name an existing")
144		fmt.Println("  saved seq, otherwise the command fails.")
145		fmt.Println()
146		fmt.Println("  In health output, a node id or version containing whitespace, quotes,")
147		fmt.Println("  backslashes or control characters is shown as a quoted JSON string")
148		fmt.Println("  (newlines as \\n, tabs as \\t, other control characters as \\uXXXX),")
149		fmt.Println("  so every result stays on its own line; the stored text is unchanged.")
150		fmt.Println()
151		fmt.Println("  history  --node ID             node id (required)")
152		fmt.Println("           --data-dir DIR        data directory")
153		fmt.Println()
154		fmt.Println("data storage:")
155		fmt.Println("  One file per node under <data-dir>:")
156		fmt.Println("    nodes/<hex-node-id>.json for short node ids")
157		fmt.Println("    slots/<sha256-node-id>.json for ids too long for a file name")
158		fmt.Println("  A node id of any length is stored and queried by its full text;")
159		fmt.Println("  long ids are never rejected, truncated or renamed.")
160		fmt.Println("  Writes are atomic and the directory is locked for concurrent access.")
161		fmt.Println("  Corrupt data is refused, never silently cleared.")
162	}
163	
164	func newFlagSet(name string) *flag.FlagSet {
165		fs := flag.NewFlagSet(name, flag.ContinueOnError)
166		fs.SetOutput(os.Stderr)
167		fs.Usage = func() { heartbeatUsage() }
168		return fs
169	}
170	
171	func cmdSubmit(args []string) {
172		fs := newFlagSet("heartbeat submit")
173		dataDir := fs.String("data-dir", defaultDataDir(), "data directory")
174		receiveStr := fs.String("receive-time", "", "receive time (RFC3339); default: now")
175		if err := fs.Parse(args); err != nil {
176			if err == flag.ErrHelp {
177				os.Exit(0)
178			}
179			os.Exit(2)
180		}
181		if fs.NArg() != 0 {
182			die("submit takes no positional arguments; heartbeats are read from stdin")
183		}
184	
185		receiveTime := parseTimeFlag(*receiveStr, "--receive-time")
186	
187		data, err := io.ReadAll(os.Stdin)
188		if err != nil {
189			die("cannot read stdin: %v", err)
190		}
191		records, err := edgefleet.ParseHeartbeats(data, receiveTime)
192		if err != nil {
193			die("invalid input: %v", err)
194		}
195	
196		store, err := edgefleet.OpenStore(*dataDir)
197		if err != nil {
198			die("%v", err)
199		}
200		newCount, dupCount, err := store.Submit(records, receiveTime)
201		if err != nil {
202			die("%v", err)
203		}
204		fmt.Printf("submitted: new=%d duplicate=%d\n", newCount, dupCount)
205	}
206	
207	func cmdHealth(args []string) {
208		fs := newFlagSet("heartbeat health")
209		dataDir := fs.String("data-dir", defaultDataDir(), "data directory")
210		node := fs.String("node", "", "node id (required)")
211		atStr := fs.String("at", "", "query time (RFC3339); default: now")
212		expectedVersion := fs.String("expected-version", "", "expected version (required)")
213		toleratedMisses := fs.Int("tolerated-misses", -1, "tolerated missed duties, >= 0 (required)")
214		missedSinceSeq := fs.Int64("missed-since-seq", 0, "seq of a saved heartbeat to use as the missed-duty baseline; must be > 0 and exist for the node")
215		if err := fs.Parse(args); err != nil {
216			if err == flag.ErrHelp {
217				os.Exit(0)
218			}
219			os.Exit(2)
220		}
221		if *node == "" {
222			die("--node is required")
223		}
224		if *expectedVersion == "" {
225			die("--expected-version is required")
226		}
227		if *toleratedMisses < 0 {
228			die("--tolerated-misses is required and must be >= 0")
229		}
230		if isFlagPassed(fs, "missed-since-seq") && *missedSinceSeq <= 0 {
231			die("--missed-since-seq must be a positive integer")
232		}
233	
234		at := parseTimeFlag(*atStr, "--at")
235	
236		store, err := edgefleet.OpenStore(*dataDir)
237		if err != nil {
238			die("%v", err)
239		}
240	
241		var result edgefleet.HealthResult
242		if isFlagPassed(fs, "missed-since-seq") {
243			result, err = store.HealthSince(*node, at, *expectedVersion, *toleratedMisses, *missedSinceSeq)
244		} else {
245			result, err = store.Health(*node, at, *expectedVersion, *toleratedMisses)
246		}
247		if err != nil {
248			die("%v", err)
249		}
250	
251		// Node id and version go through the shared display rule: text that would
252		// break the one-line format (newlines, tabs, quotes, backslashes, control
253		// characters) is shown as a quoted JSON string, so a health query always
254		// prints exactly one line — two with a missed-duty baseline — and node
255		// text can never masquerade as extra fields or a second result line.
256		if result.Status == "notelemetry" {
257			fmt.Printf("node=%s status=无遥测 findings=[无遥测]\n", edgefleet.DisplayText(result.NodeID))
258			return
259		}
260		fmt.Printf("node=%s status=%s seq=%d collected_at=%s version=%s height=%d missed=%d findings=%v\n",
261			edgefleet.DisplayText(result.NodeID), result.Status, result.Seq, result.CollectedAt.Format(time.RFC3339),
262			edgefleet.DisplayText(result.Version), result.Height, result.Missed, result.Findings)
263		if isFlagPassed(fs, "missed-since-seq") {
264			// missed above stays cumulative; this line states the alarm basis.
265			if result.NewMissedKnown {
266				fmt.Printf("baseline_seq=%d baseline_missed=%d new_missed=%d tolerated_misses=%d\n",
267					result.BaselineSeq, result.BaselineMissed, result.NewMissed, *toleratedMisses)
268			} else {
269				fmt.Printf("baseline_seq=%d baseline_missed=%d new_missed=无法判断 tolerated_misses=%d\n",
270					result.BaselineSeq, result.BaselineMissed, *toleratedMisses)
271			}
272		}
273	}
274	
275	// isFlagPassed reports whether the named flag was explicitly set on the
276	// command line, so an optional flag with a zero default can be distinguished
277	// from its absence.
278	func isFlagPassed(fs *flag.FlagSet, name string) bool {
279		passed := false
280		fs.Visit(func(f *flag.Flag) {
281			if f.Name == name {
282				passed = true
283			}
284		})
285		return passed
286	}
287	
288	func cmdHistory(args []string) {
289		fs := newFlagSet("heartbeat history")
290		dataDir := fs.String("data-dir", defaultDataDir(), "data directory")
291		node := fs.String("node", "", "node id (required)")
292		if err := fs.Parse(args); err != nil {
293			if err == flag.ErrHelp {
294				os.Exit(0)
295			}
296			os.Exit(2)
297		}
298		if *node == "" {
299			die("--node is required")
300		}
301	
302		store, err := edgefleet.OpenStore(*dataDir)
303		if err != nil {
304			die("%v", err)
305		}
306		records, err := store.History(*node)
307		if err != nil {
308			die("%v", err)
309		}
310		if len(records) == 0 {
311			fmt.Printf("node=%s no heartbeats\n", *node)
