		for i, want := range tc.want {
			if !hist[i].Equal(want) {
				t.Errorf("node %q: record %d = %+v, want %+v", tc.node, i+1, hist[i], want)
			}
		}
		if hist[0].Seq >= hist[1].Seq {
			t.Errorf("node %q: history not ascending by seq: %+v", tc.node, hist)
		}
	}
}
